import { tags } from "typia";

/**
 * Aggregated review and rating summary statistics for a SKU and its parent
 * product, materialized from customer reviews by business batch logic. Used for
 * catalog, product page, and ranking/scoring display. Derived from
 * shopping_review_rating_aggregates table; includes SKU- and product-level
 * metrics for customer-facing and search/sort UIs.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingReviewRatingAggregate = {
  /**
   * Unique identifier for the review and rating aggregate. References the
   * primary key in shopping_review_rating_aggregates.
   */
  id: string & tags.Format<"uuid">;

  /** The UUID of the SKU for these review statistics (shopping_skus.id). */
  shopping_sku_id: string & tags.Format<"uuid">;

  /**
   * The parent product's UUID for SKU-level aggregation
   * (shopping_products.id).
   */
  shopping_product_id: string & tags.Format<"uuid">;

  /**
   * Total number of visible, eligible customer reviews for this SKU, as last
   * aggregated.
   */
  review_count: number & tags.Type<"int32">;

  /** SKU-level average rating (1.0–5.0 scale, one decimal precision). */
  average_rating: number;

  /** Sum of review counts across all SKUs for this product. */
  product_review_count: number & tags.Type<"int32">;

  /**
   * Weighted product-wide average rating, across all SKUs (one decimal
   * precision).
   */
  product_average_rating: number;

  /** ISO 8601 timestamp when this aggregate was last updated/refreshed. */
  updated_at: string & tags.Format<"date-time">;
};
